import java.util.HashSet;
import java.util.Set;

public class SortedSetOpsTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Set<String> a = new HashSet<>(java.util.List.of("cat", "dog", "ant"));
        Set<String> b = new HashSet<>(java.util.List.of("dog", "emu", "ant"));
        try {
            check("union is sorted", "[ant, cat, dog, emu]", String.valueOf(SortedSetOps.union(a, b)));
            check("intersection is sorted", "[ant, dog]", String.valueOf(SortedSetOps.intersection(a, b)));
            check("input a unchanged", 3, a.size());
            check("input b unchanged", 3, b.size());

            Set<String> odd = new HashSet<>(java.util.List.of("x"));
            Set<String> even = new HashSet<>(java.util.List.of("y"));
            check("disjoint intersection is empty", "[]", String.valueOf(SortedSetOps.intersection(odd, even)));
            check("disjoint union has both", "[x, y]", String.valueOf(SortedSetOps.union(odd, even)));

            check("union with empty set", "[x]", String.valueOf(SortedSetOps.union(odd, new HashSet<>())));
            check("union returns a TreeSet", true,
                    SortedSetOps.union(odd, even) instanceof java.util.TreeSet);
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception: " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

