import java.util.Set;
import java.util.TreeSet;

public class SortedSetOps {

    public static TreeSet<String> union(Set<String> a, Set<String> b) {
        TreeSet<String> result = new TreeSet<>(a);
        result.addAll(b);
        return result;
    }

    public static TreeSet<String> intersection(Set<String> a, Set<String> b) {
        TreeSet<String> result = new TreeSet<>(a);
        result.retainAll(b);
        return result;
    }
}
